for en, es in R:
    n = s.count(en)
    assert n >= 1, "missing: " + en[:80]
    s = s.replace(en, es)
# the reference list itself stays in English (APA titles); mark it
s = s.replace('<ul class="refs">', '<ul class="refs" lang="en">')
(ROOT / "es" / "index.html").write_text(s)
print("wrote es/index.html")
